/**
 * PIS — Cetak "Slip Gaji" ke PDF, tampilannya mengikuti template resmi
 * (slip_gaji_template.xlsx) yang dipakai perusahaan — logo, alamat kantor,
 * blok ALLOWANCE/DEDUCTION 2 kolom, & tanda tangan HRD di-render ulang
 * persis susunannya lewat jsPDF (client-side), bukan dari file Excel-nya
 * langsung (supaya bisa dicetak per-karyawan dari data yang sudah ada di
 * sistem, bukan diisi manual satu-satu di Excel).
 *
 * ISI SLIP DIAMBIL LANGSUNG DARI "DATA QUERY" (bukan dari Payslip yang
 * sudah diringkas) — sesuai permintaan: "sesuaikan isi cocokan dengan
 * data query". Data Query sudah punya SEMUA rincian ALLOWANCE/DEDUCTION
 * granular (BASIC SALARY, ALLOWANCE JABATAN, JHT, JKK, JKM, BPJS, TAX,
 * dst) persis skema query_all_area.xlsx — jadi tidak ada data yang perlu
 * ditebak/dikira-kira, tinggal dipetakan 1:1 ke posisi masing-masing di
 * template.
 *
 * Dipasang sebagai tombol "🖨️" tambahan di kolom "Aksi" pada tabel "Data
 * Query" (pis-data-query.js) — lapisan tambahan di atas lapisan tambahan
 * lain, tidak mengubah pis-data-query.js itu sendiri (supaya kedua file
 * tetap independen & aman di-update terpisah).
 *
 * Kenapa jsPDF (client-side), bukan generate PDF di server (worker.js)?
 * Situs ini sudah memuat jsPDF untuk fitur "Generate PDF" versi lama (lihat
 * catatan di pis-pkwt-button-replace.js) — jadi dipakai ulang librari yang
 * sama supaya tidak menambah dependency baru di backend Cloudflare Worker.
 * Kalau jsPDF ternyata belum termuat di halaman ini, file ini otomatis
 * memuatnya sendiri dari CDN (cdnjs) sebagai fallback.
 */
(function () {
  "use strict";

  // ============================================================
  // Aset visual — di-ekstrak langsung dari slip_gaji_template.xlsx
  // (xl/media/image1.png = logo PIS, image2.png = stempel, image3.png =
  // tanda tangan HRD) supaya PDF hasil cetak identik dengan template asli.
  // ============================================================
  const PIS_LOGO_B64 = "";
  const PIS_STAMP_B64 = "";
  const PIS_SIGN_B64 = "";

  // ============================================================
  // Terbilang Rupiah — algoritma PERSIS sama dengan terbilangRupiah() di
  // worker.js (satuan/belas/puluh/ratus/ribu/juta/miliar/triliun), supaya
  // teks di PDF konsisten dengan yang dipakai di sistem.
  // ============================================================
  const TERBILANG_SATUAN = ["", "Satu", "Dua", "Tiga", "Empat", "Lima", "Enam", "Tujuh", "Delapan", "Sembilan", "Sepuluh", "Sebelas"];
  function terbilangAngka(n) {
    n = Math.floor(n);
    if (n < 12) return TERBILANG_SATUAN[n];
    if (n < 20) return terbilangAngka(n - 10) + " Belas";
    if (n < 100) return (terbilangAngka(Math.floor(n / 10)) + " Puluh" + (n % 10 ? " " + terbilangAngka(n % 10) : "")).trim();
    if (n < 200) return ("Seratus" + (n % 100 ? " " + terbilangAngka(n % 100) : "")).trim();
    if (n < 1000) return (terbilangAngka(Math.floor(n / 100)) + " Ratus" + (n % 100 ? " " + terbilangAngka(n % 100) : "")).trim();
    if (n < 2000) return ("Seribu" + (n % 1000 ? " " + terbilangAngka(n % 1000) : "")).trim();
    if (n < 1000000) return (terbilangAngka(Math.floor(n / 1000)) + " Ribu" + (n % 1000 ? " " + terbilangAngka(n % 1000) : "")).trim();
    if (n < 1000000000) return (terbilangAngka(Math.floor(n / 1000000)) + " Juta" + (n % 1000000 ? " " + terbilangAngka(n % 1000000) : "")).trim();
    if (n < 1000000000000) return (terbilangAngka(Math.floor(n / 1000000000)) + " Miliar" + (n % 1000000000 ? " " + terbilangAngka(n % 1000000000) : "")).trim();
    return (terbilangAngka(Math.floor(n / 1000000000000)) + " Triliun" + (n % 1000000000000 ? " " + terbilangAngka(n % 1000000000000) : "")).trim();
  }
  function terbilangRupiah(nominal) {
    const n = Math.floor(Math.abs(Number(nominal) || 0));
    if (n === 0) return "Nol Rupiah";
    return (terbilangAngka(n) + " Rupiah").replace(/\s+/g, " ").trim();
  }

  function fmtRupiah(v) {
    const n = Number(v) || 0;
    return "Rp " + Math.round(n).toLocaleString("id-ID");
  }
  function fmtPeriode(periode) {
    if (!periode) return "-";
    const BULAN = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
    const m = String(periode).match(/^(\d{4})-(\d{2})$/);
    if (!m) return String(periode);
    const idx = parseInt(m[2], 10) - 1;
    return `${BULAN[idx] || m[2]} ${m[1]}`;
  }

  // ============================================================
  // Muat jsPDF — pakai yang sudah termuat di halaman (fitur "Generate PDF"
  // versi lama) kalau ada, atau muat sendiri dari CDN sebagai fallback.
  // ============================================================
  let jsPDFLoaderPromise = null;
  function getJsPDFCtor() {
    if (window.jspdf && window.jspdf.jsPDF) return window.jspdf.jsPDF;
    if (window.jsPDF) return window.jsPDF;
    return null;
  }
  function ensureJsPDF() {
    const existing = getJsPDFCtor();
    if (existing) return Promise.resolve(existing);
    if (jsPDFLoaderPromise) return jsPDFLoaderPromise;
    jsPDFLoaderPromise = new Promise((resolve, reject) => {
      const script = document.createElement("script");
      script.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
      script.onload = () => {
        const ctor = getJsPDFCtor();
        if (ctor) resolve(ctor);
        else reject(new Error("jsPDF gagal dimuat."));
      };
      script.onerror = () => reject(new Error("Gagal memuat jsPDF dari CDN."));
      document.head.appendChild(script);
    });
    return jsPDFLoaderPromise;
  }

  function getToken() {
    try { return localStorage.getItem("token") || sessionStorage.getItem("token"); } catch { return null; }
  }
  async function fetchDataQueryRecord(id) {
    const token = getToken();
    const res = await fetch(`/api/apps/entities/DataQuery/${id}`, {
      headers: token ? { "X-Employee-Token": token } : {},
    });
    if (!res.ok) return null;
    return res.json().catch(() => null);
  }

  function toast(message, kind) {
    const el = document.createElement("div");
    el.style.cssText =
      "position:fixed;top:16px;left:50%;transform:translateX(-50%);z-index:99999;padding:12px 18px;border-radius:10px;font:13px system-ui,sans-serif;box-shadow:0 6px 20px rgba(0,0,0,.18);max-width:90vw;text-align:center;color:#fff;background:" +
      (kind === "fail" ? "#7b1a1a" : "#1a7b2c") + ";";
    el.textContent = message;
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 4500);
  }

  // ============================================================
  // Susunan baris ALLOWANCE & DEDUCTION — key HARUS persis nama kolom
  // Data Query (lihat DATA_QUERY_COLUMNS / grup ALLOWANCE-DEDUCTION di
  // worker.js) supaya "cocok dengan Data Query" seperti diminta. Baris
  // "PEMBAYARAN LAIN-LAIN" di template digabung dari 4 kolom potongan
  // lain-lain yang ada di Data Query (pembayaran_lain_1/2/3 + fix BPJS
  // mandiri), karena templatenya hanya menyediakan 1 baris untuk itu.
  // ============================================================
  const ALLOWANCE_ROWS = [
    ["BASIC SALARY", "basic_salary"],
    ["ADJUSMENT SALARY", "adjustment_salary"],
    ["ALLOWANCE KEHADIRAN", "allowance_kehadiran"],
    ["ADJUSTMENT NEW EMPLOYEE", "adjustment_new_employee"],
    ["ALLOWANCE JABATAN", "allowance_jabatan"],
    ["ALLOWANCE TRANSPORT", "allowance_transport"],
    ["ALLOWANCE ACTING", "allowance_acting"],
    ["ALLOWANCE PULSA", "allowance_pulsa"],
    ["JHT 3.7%", "jht_perusahaan"],
    ["JKK 0.24%", "jkk_perusahaan"],
    ["JKM 0.3%", "jkm_perusahaan"],
    ["BPJS KES 4%", "bpjs_kes_perusahaan"],
    ["TUNJANGAN PENSIUN 2%", "tunjangan_pensiun_perusahaan"],
    ["LONG SHIFT", "long_shift"],
    ["PREMI IN", "premi_in"],
    ["INS. PRODUKTIFITAS", "ins_produktifitas"],
  ];
  const DEDUCTION_ROWS = [
    ["KETIDAKHADIRAN", "ketidakhadiran"],
    ["PEMBAYARAN LAIN-LAIN", "__pembayaran_lain_gabungan__"],
    ["JHT 3.7%", "jht_karyawan"],
    ["JHT EMPLOYEE 2%", "jht_employee_2"],
    ["JKK 0.24%", "jkk_karyawan"],
    ["JKM 0.3%", "jkm_karyawan"],
    ["BPJS KES 5%", "bpjs_kes_karyawan"],
    ["IURAN PENSIUN", "iuran_pensiun"],
    ["IURAN PENSIUN KARYAWAN", "iuran_pensiun_karyawan"],
    ["PREMI OUT", "premi_out"],
    ["TAX", "tax"],
  ];
  function numOf(rec, key) {
    if (key === "__pembayaran_lain_gabungan__") {
      return (
        (Number(rec.pembayaran_lain_1) || 0) +
        (Number(rec.pembayaran_lain_2) || 0) +
        (Number(rec.pembayaran_lain_3) || 0) +
        (Number(rec.pembayaran_lain_fix_bpjs_mandiri) || 0)
      );
    }
    return Number(rec[key]) || 0;
  }

  // ============================================================
  // Bangun PDF — layout mengikuti susunan slip_gaji_template.xlsx:
  // header (logo + judul + periode) → info karyawan + alamat kantor →
  // 2 kolom ALLOWANCE/DEDUCTION → total & terbilang → tanda tangan HRD.
  // ============================================================
  async function buildPayslipPdf(rec) {
    const JsPDF = await ensureJsPDF();
    const doc = new JsPDF({ unit: "mm", format: "a4" });
    const pageW = 210;
    const marginX = 15;
    let y = 14;

    // — Header: logo + "INTEGRATED" (persis lockup di template) —
    try { doc.addImage(PIS_LOGO_B64, "PNG", marginX, y - 3, 16, 11); } catch {}
    doc.setFont("helvetica", "bold");
    doc.setFontSize(13);
    doc.setTextColor(47, 84, 150); // #2F5496, warna teks "INTEGRATED" di template
    doc.text("INTEGRATED", marginX + 19, y + 5);
    doc.setTextColor(0, 0, 0);

    doc.setFontSize(15);
    doc.text("SLIP GAJI", pageW - marginX, y + 2, { align: "right" });
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text(`Periode Kerja : ${fmtPeriode(rec.periode)}`, pageW - marginX, y + 9, { align: "right" });

    y += 16;
    doc.setDrawColor(180, 180, 180);
    doc.line(marginX, y, pageW - marginX, y);
    y += 7;

    // — Info karyawan (kiri) & alamat kantor (kanan) —
    const infoRows = [
      ["BRANCH", rec.branch || "-"],
      ["BANK", rec.bank_name || "-"],
      ["NAMA", rec.name || "-"],
      ["JABATAN", rec.position || "-"],
      ["NIK", rec.employee_no || "-"],
      ["ENTITY", rec.entity || "-"],
      ["AREA TUGAS", rec.cost_center || "-"],
    ];
    doc.setFontSize(9.5);
    let infoY = y;
    infoRows.forEach(([label, value]) => {
      doc.setFont("helvetica", "bold");
      doc.text(label, marginX, infoY);
      doc.text(":", marginX + 26, infoY);
      doc.setFont("helvetica", "normal");
      doc.text(String(value), marginX + 30, infoY);
      infoY += 5.4;
    });

    const addressX = 112;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    const addressLines = [
      "HEAD OFFICE",
      "Jl. Raya Bukit Jl. Nusa Indah No.061, Serua, Kec. Ciputat",
      "15411 - Indonesia",
      "Phone      :   (021) 27846500",
      "Mobile     :   (+62) 81-31674-8104",
      "E-mail     :  info@pissintegrated.com",
      "Website  :  www.pissintegrated.com",
    ];
    let addrY = y;
    addressLines.forEach((line) => {
      doc.text(line, addressX, addrY);
      addrY += 4.6;
    });

    y = Math.max(infoY, addrY) + 4;
    doc.setDrawColor(180, 180, 180);
    doc.line(marginX, y, pageW - marginX, y);
    y += 7;

    // — 2 kolom ALLOWANCE / DEDUCTION —
    const colLeftX = marginX;
    const colRightX = 112;
    const colWidth = 83;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    doc.text("ALLOWANCE", colLeftX, y);
    doc.text("DEDUCTION", colRightX, y);
    let allowY = y + 6;
    let dedY = y + 6;
    doc.setFontSize(8.7);

    let totalAllowance = 0;
    ALLOWANCE_ROWS.forEach(([label, key]) => {
      const val = numOf(rec, key);
      totalAllowance += val;
      doc.setFont("helvetica", "normal");
      doc.text(label, colLeftX, allowY);
      doc.text(":", colLeftX + 46, allowY);
      doc.text(fmtRupiah(val), colLeftX + colWidth, allowY, { align: "right" });
      allowY += 4.9;
    });
    // Pakai TOTAL ALLOWANCE dari Data Query kalau sudah dihitung server;
    // fallback ke jumlah baris di atas kalau kosong (mis. baris lama yang
    // belum pernah dilewati generatePayslipBulanan).
    if (rec.total_allowance != null && rec.total_allowance !== "") totalAllowance = Number(rec.total_allowance) || totalAllowance;

    let totalDeduction = 0;
    DEDUCTION_ROWS.forEach(([label, key]) => {
      const val = numOf(rec, key);
      totalDeduction += val;
      doc.setFont("helvetica", "normal");
      doc.text(label, colRightX, dedY);
      doc.text(":", colRightX + 46, dedY);
      doc.text(fmtRupiah(val), colRightX + colWidth, dedY, { align: "right" });
      dedY += 4.9;
    });
    if (rec.total_deduction != null && rec.total_deduction !== "") totalDeduction = Number(rec.total_deduction) || totalDeduction;

    const totalsY = Math.max(allowY, dedY) + 2;
    doc.setDrawColor(150, 150, 150);
    doc.line(colLeftX, totalsY - 3, colLeftX + colWidth, totalsY - 3);
    doc.line(colRightX, totalsY - 3, colRightX + colWidth, totalsY - 3);
    doc.setFont("helvetica", "bold");
    doc.text("TOTAL ALLOWANCE", colLeftX, totalsY);
    doc.text(fmtRupiah(totalAllowance), colLeftX + colWidth, totalsY, { align: "right" });
    doc.text("TOTAL DEDUCTION", colRightX, totalsY);
    doc.text(fmtRupiah(totalDeduction), colRightX + colWidth, totalsY, { align: "right" });

    y = totalsY + 8;
    doc.setDrawColor(180, 180, 180);
    doc.line(marginX, y, pageW - marginX, y);
    y += 7;

    // — Ringkasan pembayaran & terbilang —
    const netSalary = rec.net_salary != null && rec.net_salary !== "" ? Number(rec.net_salary) : totalAllowance - totalDeduction;
    const gajiDiterima = rec.full_salary != null && rec.full_salary !== "" ? Number(rec.full_salary) : netSalary;
    const summaryRows = [
      ["PEMBAYARAN KE NO. REK", rec.bank_name || "-"],
      ["NO. REK", rec.bank_account || "-"],
      ["TOTAL GAJI BERSIH", fmtRupiah(netSalary)],
      ["GAJI DI TERIMA", fmtRupiah(gajiDiterima)],
    ];
    doc.setFontSize(9.5);
    summaryRows.forEach(([label, value]) => {
      doc.setFont("helvetica", "bold");
      doc.text(label, marginX, y);
      doc.text(":", marginX + 40, y);
      doc.setFont("helvetica", "normal");
      doc.text(String(value), marginX + 44, y);
      y += 5.6;
    });
    doc.setFont("helvetica", "bold");
    doc.text("TERBILANG", marginX, y);
    doc.text(":", marginX + 40, y);
    doc.setFont("helvetica", "italic");
    doc.text(`( ${terbilangRupiah(gajiDiterima)} )`, marginX + 44, y);

    // — Tanda tangan HRD (stempel + tanda tangan, persis template) —
    const sigX = 150;
    const sigY = y - 4;
    try { doc.addImage(PIS_STAMP_B64, "PNG", sigX - 6, sigY - 2, 24, 19); } catch {}
    try { doc.addImage(PIS_SIGN_B64, "PNG", sigX, sigY, 30, 22); } catch {}
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9.5);
    doc.text("HRD", sigX + 15, sigY + 26, { align: "center" });
    doc.text("( Moch. A. Saptoadjie )", sigX + 15, sigY + 31, { align: "center" });

    return doc;
  }

  async function printPayslip(dataQueryId) {
    const rec = await fetchDataQueryRecord(dataQueryId);
    if (!rec) {
      toast("Data Query untuk baris ini tidak ditemukan.", "fail");
      return;
    }
    try {
      const doc = await buildPayslipPdf(rec);
      const filename = `Slip Gaji - ${rec.name || rec.employee_no || "Karyawan"} - ${fmtPeriode(rec.periode)}.pdf`;
      doc.save(filename);
    } catch (e) {
      toast("Gagal membuat PDF: " + (e.message || e), "fail");
    }
  }
  // Dipanggil dari console browser (F12) untuk uji cepat tanpa lewat
  // tombol: window.__pisPrintPayslip("<id DataQuery>")
  window.__pisPrintPayslip = printPayslip;

  // ============================================================
  // Suntik tombol "🖨️" di kolom Aksi tabel "Data Query" (pis-data-query.js)
  // ============================================================
  function injectPrintButtons() {
    document.querySelectorAll("table.pisdq-table tbody tr[data-id]").forEach((tr) => {
      const id = tr.getAttribute("data-id");
      if (!id) return;
      const cells = tr.querySelectorAll("td");
      const aksiCell = cells[cells.length - 1];
      if (!aksiCell || aksiCell.querySelector(".pispdf-print-btn")) return;
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "pisdq-action-btn pispdf-print-btn";
      btn.title = "Cetak Slip Gaji (PDF)";
      btn.textContent = "🖨️";
      btn.style.color = "#7B1A2C";
      btn.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        printPayslip(id);
      });
      aksiCell.appendChild(btn);
    });
  }

  const observer = new MutationObserver(() => injectPrintButtons());
  observer.observe(document.body, { childList: true, subtree: true });
  setInterval(injectPrintButtons, 1500);
  injectPrintButtons();
})();
